<template>
  <div class="creative-page">
    <div ref="containerRef" class="creative-container"></div>

    <!-- 顶部状态栏 -->
    <div v-if="showDebugViewer" class="creative-hud">
      <div class="hud-title">🎨 Creative Mode (Fly)</div>
      <div class="hud-row">
        <span class="label">Status:</span>
        <span class="value" :class="statusClass">{{ status }}</span>
      </div>
    </div>

    <!-- 底部操作提示 -->
    <div v-if="showDebugViewer" class="creative-help">
      <div class="help-title">操作说明</div>
      <ul>
        <li><b>WASD</b> 控制前后左右移动</li>
        <li><b>QE</b> 控制上下升降</li>
        <li>长按 <b>Shift</b> 加速</li>
        <li><b>左键</b> 按住拖拽旋转视角</li>
        <li><b>滚轮</b> 放大/缩小（沿相机前后位移）</li>
      </ul>
    </div>
  </div>
</template>

<script setup lang="ts">
import { ref, onMounted, computed } from 'vue';
import { useRoute } from 'vue-router';
import {
  lightModule,
  ViewerSDK,
  // Wave-1 (2026-07 pluggable-refactor)：从 sdk 必装链摘除，改由 viewer 入口 extraModules 显式装配
  npcManagerModule,
  npcSystemModule,
  debugModule,
} from '@tencent/viewer-sdk';
import { hasNewRouteParams, buildURLParamsFromRoute, getShowDebugViewerFromRoute, parseURLParamsFromQuery } from '../../utils/route-params';

const containerRef = ref<HTMLDivElement>();
const sdk = new ViewerSDK();
const route = useRoute();

const showDebugViewer = ref(getShowDebugViewerFromRoute(route));

const status = ref('Loading...');
const statusClass = computed(() => {
  if (status.value.startsWith('Ready')) return 'ok';
  if (status.value.startsWith('Error')) return 'err';
  return 'info';
});

// 默认从 public/modelList.json 取第一个场景
async function resolveSceneUrl(): Promise<string> {
  const urlParams = hasNewRouteParams(route)
    ? buildURLParamsFromRoute(route)
    : parseURLParamsFromQuery();
  if (urlParams.sceneUrl) return urlParams.sceneUrl;
  try {
    const resp = await fetch('/modelList.json');
    const list = await resp.json();
    const first = Array.isArray(list) ? list[0] : (list?.list?.[0] ?? null);
    if (first?.configUrl) return first.configUrl as string;
    if (first?.sceneUrl) return first.sceneUrl as string;
  } catch (e) {
    console.warn('[CreativeViewer] 读取 modelList.json 失败，使用空 sceneUrl', e);
  }
  return '';
}

onMounted(async () => {
  if (!containerRef.value) {
    status.value = 'Error: container not ready';
    return;
  }

  try {
    const sceneUrl = await resolveSceneUrl();
    console.log('[CreativeViewer] Starting with sceneUrl=', sceneUrl);

    // 创造模式初始化
    await sdk.init({
      container: containerRef.value,
      sceneUrl,
      // @ts-ignore interactionRef 在创造模式下不使用
      interactionRef: null,
      defaultOperationMode: 'dual',
      enableCliffDetection: false,
      mode: 'creative',
      // Wave-1 (2026-07 pluggable-refactor)：SDK v2.2.0 后 npc/debug 从必装链摘除，此处显式补装保持行为等价
      // 注：animationModule 已于 20260714 中央化并重回 SDK 必装链（character/npc 硬依赖），无需在此补装
      extraModules: [lightModule, npcManagerModule, npcSystemModule, debugModule],
      hideDebugViewer: !showDebugViewer.value,
    });

    // 启动渲染循环（sdk.init 不会自动启动，必须显式调用）
    sdk.animate();

    status.value = 'Ready';
  } catch (err) {
    console.error('[CreativeViewer] init failed', err);
    status.value = `Error: ${(err as Error).message ?? err}`;
  }
});
</script>

